import {search,move} from './core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mode='test',view='inventory',query='',stream,timer,db,cameraSession=0;const device=localStorage.mtDevice||crypto.randomUUID();localStorage.mtDevice=device;
const seed=()=>({version:1,products:[['Ketchup de casa','TEST-001','Casa','Botella · 400 g',6,2,'A','1','01','🍅'],['Crema de casa','TEST-002','Casa','Envase · 250 ml',2,3,'A','1','02','🥛'],['Filtro de aceite (ficticio)','FIC-101','DemoParts','Rosca M20 · motor 1.6',12,4,'B','2','01','⚙'],['Pastillas de freno (ficticias)','FIC-102','DemoParts','Delanteras · sedan',0,2,'B','3','02','🔧']].map(([name,code,brand,spec,qty,min,shelf,level,box,emoji])=>({id:crypto.randomUUID(),name,code,brand,spec,qty,min,shelf,level,box,emoji})),events:[]});
const key=()=>`mi-torno-v1-${mode}`;
function load(){try{db=JSON.parse(localStorage.getItem(key()))}catch{db=null}if(!db){db={version:1,products:[],events:[]};save()}if(mode==='test'&&!db.emptyStartApplied){const examples=new Map([['TEST-001','Ketchup de casa'],['TEST-002','Crema de casa'],['FIC-101','Filtro de aceite (ficticio)'],['FIC-102','Pastillas de freno (ficticias)']]);const removed=new Set(db.products.filter(p=>examples.get(p.code)===p.name&&!db.events.some(e=>e.productId===p.id)).map(p=>p.id));db.products=db.products.filter(p=>!removed.has(p.id));db.emptyStartApplied=true;save()}render()}
function save(){try{localStorage.setItem(key(),JSON.stringify(db))}catch{throw Error('No se pudo guardar. Exporta una copia o reduce el tamaño de las fotos.')}}
function commit(fn){const old=structuredClone(db);try{fn();save();render();return true}catch(e){db=old;toast(e.message);return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function modal(html){stop();$('#dialogBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){stop();$('#modal').close()}function stop(){cameraSession++;clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());stream=null}$('#close').onclick=close;$('#modal').addEventListener('cancel',stop);
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#title').textContent=({inventory:'Inventario',history:'Movimientos',alerts:'Stock bajo',settings:'Datos y ajustes'})[view];$('#banner').textContent=mode==='test'?'◈ Estás en pruebas. Experimenta con libertad: el inventario real está separado.':'Inventario real · Guardado únicamente en este navegador. Exporta copias de seguridad.';const low=db.products.filter(p=>p.qty<=p.min);$('#stats').innerHTML=[['Productos registrados',db.products.length],['Unidades disponibles',db.products.reduce((a,p)=>a+p.qty,0)],['Productos con stock bajo',low.length]].map(([t,n])=>`<div class="stat"><span>${t}</span><b>${n}</b></div>`).join('');
if(view==='settings'){settings();return}if(view==='history'){$('#content').innerHTML=db.events.length?db.events.map(e=>`<div class="history-row"><div><b>${esc(e.name)}</b><small>${esc(({in:'Entrada',out:'Salida',count:'Conteo',create:'Alta',location:'Ubicación'})[e.type]||e.type)} · ${esc(e.note)}<br>${new Date(e.at).toLocaleString('es-SV')}</small></div><div>${e.before} → <b>${e.after}</b></div></div>`).join(''):'<div class="empty">Todavía no hay movimientos. Registra tu primera entrada.</div>';return}
$('#content').innerHTML=`<div class="toolbar"><input id="search" placeholder="Buscar nombre, código, marca, medidas o ubicación…" aria-label="Buscar productos" value="${esc(query)}"><span>${view==='alerts'?'En mínimo o por debajo':'CATÁLOGO DE PRODUCTOS'}</span></div><div class="grid" id="grid"></div>`;$('#search').oninput=e=>{query=e.target.value;cards()};cards();}
function cards(){const ps=search(db.products,query).filter(p=>view!=='alerts'||p.qty<=p.min);$('#grid').innerHTML=ps.map(p=>`<article class="card"><div class="visual">${p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.name)}">`:esc(p.emoji||'⚙')}</div><div class="card-body"><span class="code">${esc(p.code)}</span><h3>${esc(p.name)}</h3><div class="meta">${esc(p.brand)} · ${esc(p.spec)}</div><div class="stock"><div><strong>${p.qty}</strong> <small>uds.</small></div><span class="badge ${p.qty<=p.min?'low':''}">${p.qty<=p.min?'Stock bajo':'Disponible'}</span></div><p class="meta">⌖ Estante ${esc(p.shelf||'—')} / Nivel ${esc(p.level||'—')} / Caja ${esc(p.box||'—')}</p><button data-id="${p.id}">Ver ficha y registrar</button></div></article>`).join('')||'<div class="empty">No hay productos para mostrar.</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id))}
function detail(id){const p=db.products.find(p=>p.id===id);modal(`<span class="badge">${mode==='test'?'PRUEBAS':'REAL'}</span><h2>${esc(p.name)}</h2><p>${esc(p.code)} · ${esc(p.brand)}<br>${esc(p.spec)}<br>Estante ${esc(p.shelf)} / Nivel ${esc(p.level)} / Caja ${esc(p.box)}</p><h3>${p.qty} unidades · Mínimo ${p.min}</h3><form id="movement"><label>Operación<select name="type"><option value="in">Sumar entrada</option><option value="out">Registrar salida</option><option value="count">Corregir con conteo físico</option></select></label><label>Cantidad (en conteo: total contado)<input name="amount" type="number" min="0" step="1" required value="1"></label><label>Motivo / referencia<input name="note" maxlength="180" placeholder="Ej. compra, trabajo o revisión"></label><p id="difference"></p><button class="primary">Confirmar movimiento</button></form><button id="edit">Corregir ficha o cambiar ubicación</button>`);const f=$('#movement');function diff(){const n=Number(f.amount.value);$('#difference').textContent=f.type.value==='count'?`Conteo: ${p.qty} → ${n}. Diferencia: ${n-p.qty} unidades.`:'La cantidad se aplicará al confirmar.'}f.oninput=diff;diff();f.onsubmit=e=>{e.preventDefault();if(commit(()=>move(db,id,f.type.value,Number(f.amount.value),f.note.value,device))){close();toast('Movimiento guardado')}};$('#edit').onclick=()=>productForm(p)}
function field(label,name,value='',type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['name','code'].includes(name)?'required':''} ${type==='number'?'min="0" step="1"':''} maxlength="160"></label>`}
function productForm(p={},code=''){modal(`<h2>${p.id?'Editar producto':'Nuevo producto'}</h2><form id="product"><div class="fields">${field('Nombre','name',p.name)}${field('Código único','code',p.code||code)}<div class="wide"><button type="button" id="scanProductCode">▥ Escanear código de barras</button><p id="productCodeStatus" role="status"></p></div>${field('Marca','brand',p.brand)}${field('Medidas / características','spec',p.spec)}${!p.id?field('Cantidad inicial','qty',0,'number'):''}${field('Stock mínimo','min',p.min||0,'number')}${field('Estante','shelf',p.shelf)}${field('Nivel','level',p.level)}${field('Caja','box',p.box)}<label class="wide">Foto (opcional)<input type="file" name="photo" accept="image/*" capture="environment"></label></div><button class="primary">${p.id?'Guardar cambios':'Crear producto'}</button></form>`);$('#scanProductCode').onclick=()=>{
const body=$('#dialogBody'),savedNodes=Array.from(body.childNodes);
const restore=()=>{stop();body.replaceChildren(...savedNodes)};
scanner({onBack:restore,onCode:value=>{
restore();const input=$('#product').elements.namedItem('code');input.value=value.trim();
const duplicate=db.products.find(x=>x.id!==p.id&&x.code.trim().toLowerCase()===value.trim().toLowerCase());
$('#productCodeStatus').textContent=duplicate?'Este código ya existe: '+duplicate.name+'. Al guardar podrás abrir su ficha para sumar o corregir.':'Código leído. Completa los datos y confirma Crear producto.';
input.focus();
}});
};$('#product').onsubmit=async e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));const duplicate=db.products.find(x=>x.code.trim().toLowerCase()===data.code.trim().toLowerCase()&&x.id!==p.id);if(duplicate){modal(`<h2>Este código ya existe</h2><p>${esc(duplicate.name)} · ${duplicate.qty} unidades. Abre su ficha para sumar una entrada, corregir un conteo o cambiar la ubicación.</p><button id="existing" class="primary">Abrir ficha existente</button>`);$('#existing').onclick=()=>detail(duplicate.id);return}let photo=p.photo||'';try{if(data.photo.size)photo=await readPhoto(data.photo)}catch(err){toast(err.message);return}if(!$('#modal').open)return;const qty=p.id?p.qty:Number(data.qty),min=Number(data.min);if(!Number.isInteger(qty)||qty<0||!Number.isInteger(min)||min<0){toast('Cantidades enteras, cero o mayores');return}if(commit(()=>{const next={...p,id:p.id||crypto.randomUUID(),name:data.name.trim(),code:data.code.trim(),brand:data.brand.trim(),spec:data.spec.trim(),shelf:data.shelf.trim(),level:data.level.trim(),box:data.box.trim(),qty,min,photo};if(!next.name||!next.code)throw Error('Completa nombre y código');if(p.id)db.products=db.products.map(x=>x.id===p.id?next:x);else db.products.push(next);db.events.unshift({id:crypto.randomUUID(),productId:next.id,name:next.name,type:p.id?'location':'create',before:p.qty||0,after:qty,note:p.id?'Ficha actualizada': 'Cantidad inicial',at:new Date().toISOString(),device,sync:'local'});})){close();toast('Producto guardado')}}}
async function readPhoto(file){if(file.size>15000000)throw Error('La foto supera 15 MB');const bitmap=await createImageBitmap(file);const c=document.createElement('canvas'),scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));c.width=bitmap.width*scale;c.height=bitmap.height*scale;c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();return c.toDataURL('image/jpeg',.75)}
function identify(code){stop();const p=db.products.find(p=>p.code.toLowerCase()===code.trim().toLowerCase());if(p)detail(p.id);else{modal(`<h2>Código sin registrar</h2><p>${esc(code)} no está en este inventario. No se consultan catálogos externos.</p><button id="newCode" class="primary">Crear producto con este código</button>`);$('#newCode').onclick=()=>productForm({},code)}}
async function scanner(options={}){
const onCode=typeof options.onCode==='function'?options.onCode:identify;
modal(`<h2>Escanear producto</h2><p>Apunta al código de barras. La lectura abre la ficha; no suma existencias automáticamente.</p><video id="camera" autoplay playsinline muted></video><p id="cameraStatus" role="status">Solicitando acceso a la cámara…</p><button id="retryCamera" type="button">Reintentar cámara</button><form id="manualCode"><label>Código de barras o impreso<input name="code" required placeholder="Escribe el código si no se puede leer"></label><button class="primary">Buscar código</button></form><p>OCR de texto impreso pendiente. Puedes escribir el código manualmente.</p>`);
if(typeof options.onBack==='function'){const back=document.createElement('button');back.type='button';back.textContent='← Volver al producto';back.onclick=()=>{stop();options.onBack()};$('#dialogBody').prepend(back)}
const session=cameraSession,video=$('#camera'),status=$('#cameraStatus');
const active=()=>session===cameraSession&&$('#modal').open&&$('#camera')===video;
$('#retryCamera').onclick=()=>scanner(options);
$('#manualCode').onsubmit=e=>{e.preventDefault();onCode(e.target.code.value)};
try{
if(!window.isSecureContext)throw Error('La cámara necesita una conexión segura. Abre la dirección HTTPS de Vercel.');
if(!navigator.mediaDevices?.getUserMedia)throw Error('Este navegador no permite acceder a la cámara. Abre la aplicación directamente en Safari o Chrome.');
const acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
if(!active()){acquired.getTracks().forEach(t=>t.stop());return}
stream=acquired;video.srcObject=acquired;await video.play();
if(!active())return;
status.textContent='Cámara activa. Comprobando lectura automática…';
let detector;
try{
if(!('BarcodeDetector' in window))throw Error();
const formats=await window.BarcodeDetector.getSupportedFormats();
if(!formats.length)throw Error();
detector=new window.BarcodeDetector({formats});
}catch{
if(active())status.textContent='Cámara activa. Este navegador no ofrece lectura automática de códigos; escribe el código de abajo para buscarlo.';
return;
}
if(!active())return;
status.textContent='Cámara activa. Coloca el código dentro de la imagen.';
async function tick(){
if(!active()||!stream)return;
try{const results=await detector.detect(video);if(!active())return;if(results.length){onCode(results[0].rawValue);return}}catch{if(active())status.textContent='Cámara activa. No se pudo leer el código; acércalo con buena luz o escríbelo abajo.'}
if(active())timer=setTimeout(tick,450);
}
tick();
}catch(e){
if(!active())return;
stop();
const messages={NotAllowedError:'El acceso a la cámara está bloqueado o fue rechazado. En los permisos de este sitio, permite Cámara y pulsa Reintentar cámara.',NotFoundError:'No se encontró una cámara disponible en este dispositivo.',NotReadableError:'No se pudo iniciar la cámara. Cierra otras aplicaciones que la estén usando y vuelve a intentar.',OverconstrainedError:'La cámara no admite la configuración solicitada. Prueba otro navegador.'};
status.textContent=messages[e.name]||e.message||'No se pudo abrir la cámara. Puedes escribir el código manualmente.';
}
}
function settings(){$('#content').innerHTML=`<div class="panel"><h2>Tu información, bajo control</h2><p>Los datos viven en este navegador y pueden perderse si se borra su almacenamiento. Cada dispositivo tiene su propio inventario. Exporta una copia después de trabajar.</p><button id="export">↓ Exportar copia JSON (${mode==='test'?'pruebas':'real'})</button></div><div class="panel"><h3>Modo de pruebas</h3><p>Limpiar borra solo productos e historial de pruebas. El inventario real se conserva.</p><button id="clear">Limpiar pruebas</button> <button id="seed">Cargar ejemplos de nuevo</button></div><div class="panel"><h3>Conexión entre equipos · Próxima etapa</h3><p>Sin backend ni sincronización activa. La arquitectura separa catálogo y movimientos con identificadores únicos, dispositivo y versión. Hace falta un servidor, usuarios y resolución de conflictos antes de usar dos equipos sobre el mismo inventario.</p><p>Instalación PWA y cámara requieren HTTPS o localhost; el modo sin conexión necesita una primera carga completa.</p></div>`;$('#export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({environment:mode,exportedAt:new Date().toISOString(),...db},null,2)],{type:'application/json'}));a.href=url;a.download=`mi-torno-${mode}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#clear').onclick=()=>{if(confirm('¿Borrar productos e historial SOLO de PRUEBAS?')){localStorage.setItem('mi-torno-v1-test',JSON.stringify({version:1,products:[],events:[]}));load();toast('Pruebas limpiadas; inventario real conservado')}};$('#seed').onclick=()=>{if(confirm('¿Reemplazar las pruebas actuales con los ejemplos?')){localStorage.setItem('mi-torno-v1-test',JSON.stringify(seed()));load();toast('Ejemplos cargados en pruebas')}}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;query='';render()});$('#mode').onchange=e=>{close();mode=e.target.value;query='';load()};$('#add').onclick=()=>productForm();$('#scan').onclick=scanner;load();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
